/**
 * Translations for the desktop error catalog beyond its Italian and English
 * source copy. The English sentence is the stable lookup key; each value is
 * `[sentence, action]` in the target language.
 */

export const ERROR_TRANSLATION_LOCALES = ["de", "es", "fr", "hu", "pt"] as const;

export type ErrorTranslationLocale = (typeof ERROR_TRANSLATION_LOCALES)[number];
export type ErrorTranslationPair = readonly [text: string, action: string];

export type ErrorTranslations = Record<ErrorTranslationLocale, ErrorTranslationPair>;

function tr(
  de: ErrorTranslationPair,
  es: ErrorTranslationPair,
  fr: ErrorTranslationPair,
  hu: ErrorTranslationPair,
  pt: ErrorTranslationPair,
): ErrorTranslations {
  return { de, es, fr, hu, pt };
}

